static uint8_t captured_pixels[8][128];
static unsigned int page_calls[8];
static sensors_snapshot_t readings;

static bool capture_page(sh1106_send_t send, uint8_t address, uint8_t page,
                         const uint8_t *pixels, int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    if ((page < 8U) && (pixels != NULL))
    {
        memcpy(captured_pixels[page], pixels, sizeof(captured_pixels[page]));
        page_calls[page]++;
    }
    return true;
}

static void reset_display(void)
{
    memset(captured_pixels, 0, sizeof(captured_pixels));
    memset(page_calls, 0, sizeof(page_calls));
    memset(&readings, 0, sizeof(readings));
    TEST_ASSERT_TRUE(display_init(0U));
}

static void finish_splash_and_transfer_dashboard(void)
{
    /* The first call leaves stabilization; the next completes the splash. */
    display_process(UINT32_MAX, &readings);
    display_process(UINT32_MAX, &readings);
    for (unsigned int i = 0U; i < 7U; i++)
    {
        display_process(UINT32_MAX, &readings);
    }
}

static void transfer_remaining_dashboard_pages(void)
{
    for (unsigned int i = 0U; i < 7U; i++)
    {
        display_process(UINT32_MAX, &readings);
    }
}

