void test_display_set_event_01(void)
{
    display_process(UINT32_MAX, &readings); /* Enter splash. */
    display_set_event("ignored during splash");
    display_process(UINT32_MAX, &readings);
    for (unsigned int i = 0U; i < 7U; i++)
    {
        display_process(UINT32_MAX, &readings);
    }
    uint8_t splash_event_page3[128];
    uint8_t splash_event_page4[128];
    memcpy(splash_event_page3, captured_pixels[3], sizeof(splash_event_page3));
    memcpy(splash_event_page4, captured_pixels[4], sizeof(splash_event_page4));

    reset_display();
    finish_splash_and_transfer_dashboard();
    TEST_ASSERT_EQUAL_MEMORY(splash_event_page3, captured_pixels[3], sizeof(splash_event_page3));
    TEST_ASSERT_EQUAL_MEMORY(splash_event_page4, captured_pixels[4], sizeof(splash_event_page4));
}

void test_display_set_event_02(void)
{
    finish_splash_and_transfer_dashboard();
    unsigned int page0_calls_before = page_calls[0];
    display_set_event("ALERT");
    display_process(UINT32_MAX, &readings);
    TEST_ASSERT_EQUAL_INT((int)(page0_calls_before + 1U), (int)page_calls[0]);
    transfer_remaining_dashboard_pages();

    uint8_t event_page3[128];
    memcpy(event_page3, captured_pixels[3], sizeof(event_page3));
    reset_display();
    finish_splash_and_transfer_dashboard();
    TEST_ASSERT_TRUE(memcmp(event_page3, captured_pixels[3], sizeof(event_page3)) != 0);
}

void test_display_set_event_03(void)
{
    finish_splash_and_transfer_dashboard();
    uint8_t empty_page3[128];
    uint8_t empty_page4[128];
    memcpy(empty_page3, captured_pixels[3], sizeof(empty_page3));
    memcpy(empty_page4, captured_pixels[4], sizeof(empty_page4));

    reset_display();
    finish_splash_and_transfer_dashboard();
    display_set_event("ALERT");
    display_process(UINT32_MAX, &readings);
    transfer_remaining_dashboard_pages();
    display_set_event(NULL);
    display_process(UINT32_MAX, &readings);
    transfer_remaining_dashboard_pages();

    TEST_ASSERT_EQUAL_MEMORY(empty_page3, captured_pixels[3], sizeof(empty_page3));
    TEST_ASSERT_EQUAL_MEMORY(empty_page4, captured_pixels[4], sizeof(empty_page4));
}

